from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/output/result.xlsx'
wb = load_workbook(path, data_only=False)
print('Workbook:', path)
print('Sheets:', wb.sheetnames)

for ws_name, max_row, min_col, max_col in [('Task', 55, 1, 12), ('Data', 40, 1, None)]:
    ws = wb[ws_name]
    if max_col is None:
        max_col = ws.max_column
    print('\n=== Sheet', ws_name, 'rows 1-%s cols %s-%s ===' % (max_row, get_column_letter(min_col), get_column_letter(max_col)))
    for r in range(1, max_row + 1):
        vals = []
        for c in range(min_col, max_col + 1):
            v = ws.cell(r, c).value
            if v is None:
                s = ''
            else:
                s = str(v)
            vals.append(s)
        print(f'{r:02d}: ' + ' | '.join(vals))

ws = wb['Task']
print('\nTask exact series codes in D:')
for rows in [(12,17),(19,24),(26,31),(35,40)]:
    print(f'Rows {rows[0]}-{rows[1]}:', [ws.cell(r,4).value for r in range(rows[0], rows[1]+1)])
print('Years H10:L10:', [ws.cell(10,c).value for c in range(8,13)])

print('\nExisting formulas/values in target ranges:')
for coord_range in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print(coord_range)
    for row in ws[coord_range]:
        print('  ' + ', '.join(f'{cell.coordinate}={cell.value!r}' for cell in row))

wsd = wb['Data']
print('\nData dimensions:', wsd.max_row, wsd.max_column)
print('Data rows 21:38 with column letters:')
for r in range(21,39):
    print(f'Row {r}:')
    for c in range(1, wsd.max_column + 1):
        v = wsd.cell(r,c).value
        if v is not None:
            print(f'  {get_column_letter(c)}{r}: {v!r}')

print('\nData candidate year header rows around 18-22:')
for r in range(18,23):
    print(f'Row {r}:', [(get_column_letter(c), wsd.cell(r,c).value) for c in range(1, wsd.max_column+1) if wsd.cell(r,c).value is not None])
